(function(){function send(name,detail){try{const payload=JSON.stringify({e:name,d:detail||{},p:location.pathname,t:Date.now(),});if(navigator.sendBeacon){navigator.sendBeacon('/api/track',new Blob([payload],{type:'application/json'}));}}catch(_){}}
document.addEventListener('click',function(e){const a=e.target.closest&&e.target.closest('a[href]');if(!a)return;const href=a.getAttribute('href')||'';if(href.indexOf('calendly.com')!==-1){send('cta_calendly_click',{href:href,text:(a.textContent||'').trim().slice(0,80)});}else if(href.indexOf('tel:')===0){send('cta_tel_click',{href:href});}},{capture:true,passive:true});document.addEventListener('DOMContentLoaded',function(){const form=document.getElementById('contactForm');if(!form)return;form.addEventListener('submit',function(){send('contact_form_submit_attempt',{});});document.addEventListener('contact:success',function(){send('contact_form_submit_success',{});});document.addEventListener('calendly.event_scheduled',function(){send('calendly_booking_complete',{});});document.addEventListener('pricing:tier',function(e){send('pricing_tier_selected',e.detail||{});});document.addEventListener('pricing:addon',function(e){send('pricing_addon_selected',e.detail||{});});document.addEventListener('pricing:cta-click',function(e){send('pricing_book_call_click',e.detail||{});});window.addEventListener('message',function(e){if(!e||!e.data||typeof e.data!=='object')return;if(e.data.event==='calendly.event_scheduled'){send('calendly_booking_complete',{});}});});})();document.addEventListener('DOMContentLoaded',function(){const scrollToTopBtn=document.getElementById('scrollToTop');if(!scrollToTopBtn)return;window.addEventListener('scroll',()=>{if(window.pageYOffset>300){scrollToTopBtn.classList.add('visible');}else{scrollToTopBtn.classList.remove('visible');}},{passive:true});scrollToTopBtn.addEventListener('click',()=>{window.scrollTo({top:0,behavior:'smooth'});});});document.addEventListener('DOMContentLoaded',function(){const cookieBanner=document.getElementById('cookieBanner');const cookieAccept=document.getElementById('cookieAccept');const cookieDecline=document.getElementById('cookieDecline');if(!cookieBanner||!cookieAccept||!cookieDecline)return;const cookieConsent=localStorage.getItem('cookieConsent');if(!cookieConsent){setTimeout(()=>{cookieBanner.classList.add('visible');},1000);}
cookieAccept.addEventListener('click',()=>{localStorage.setItem('cookieConsent','accepted');cookieBanner.classList.remove('visible');});cookieDecline.addEventListener('click',()=>{localStorage.setItem('cookieConsent','declined');cookieBanner.classList.remove('visible');});});document.addEventListener('DOMContentLoaded',function(){const mobileToggle=document.getElementById('mobileToggle');const mobileMenu=document.getElementById('mobileMenu');const navbarOverlay=document.getElementById('navbarOverlay');const body=document.body;if(!mobileToggle||!mobileMenu||!navbarOverlay)return;const closeMobileMenu=()=>{mobileMenu.classList.remove('active');navbarOverlay.classList.remove('active');body.classList.remove('menu-open');mobileToggle.setAttribute('aria-expanded','false');mobileToggle.querySelector('i').className='fi fi-rs-burger-menu';};mobileToggle.addEventListener('click',()=>{mobileMenu.classList.toggle('active');const isOpen=mobileMenu.classList.contains('active');mobileToggle.setAttribute('aria-expanded',String(isOpen));if(isOpen){navbarOverlay.classList.add('active');body.classList.add('menu-open');}else{navbarOverlay.classList.remove('active');body.classList.remove('menu-open');}
mobileToggle.querySelector('i').className=isOpen?'fi fi-rs-cross':'fi fi-rs-burger-menu';});const accordionTriggers=document.querySelectorAll('.mobile-accordion-trigger');accordionTriggers.forEach(trigger=>{trigger.addEventListener('click',()=>{const accordion=trigger.parentElement;const isActive=accordion.classList.contains('active');document.querySelectorAll('.mobile-accordion').forEach(acc=>{acc.classList.remove('active');const t=acc.querySelector('.mobile-accordion-trigger');if(t)t.setAttribute('aria-expanded','false');});if(!isActive){accordion.classList.add('active');trigger.setAttribute('aria-expanded','true');}});});navbarOverlay.addEventListener('click',()=>{closeMobileMenu();});document.addEventListener('click',(e)=>{if(mobileMenu.classList.contains('active')&&!mobileMenu.contains(e.target)&&!mobileToggle.contains(e.target)){closeMobileMenu();}});document.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&mobileMenu.classList.contains('active')){closeMobileMenu();}});const mobileLinks=document.querySelectorAll('.mobile-link, .mobile-dropdown-item, .mobile-btn');mobileLinks.forEach(link=>{link.addEventListener('click',()=>{closeMobileMenu();});});const navbar=document.querySelector('.navbar');if(navbar){const onScroll=()=>{navbar.classList.toggle('scrolled',window.pageYOffset>8);};window.addEventListener('scroll',onScroll,{passive:true});onScroll();}});document.addEventListener('DOMContentLoaded',function(){const norm=(p)=>p.replace(/index\.html$/,'').replace(/\/+$/,'')||'/';const current=norm(location.pathname);const links=document.querySelectorAll('.navbar-link[href], .dropdown-item[href], .mobile-link[href], .mobile-dropdown-item[href]');links.forEach((a)=>{if(norm(a.pathname)!==current)return;a.classList.add('active');a.setAttribute('aria-current','page');const dd=a.closest('.navbar-dropdown');if(dd)dd.querySelector('.dropdown-trigger')?.classList.add('active');const acc=a.closest('.mobile-accordion');if(acc)acc.querySelector('.mobile-accordion-trigger')?.classList.add('active');});});(function(){const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const ready=(fn)=>{if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',fn);else fn();};ready(function(){if(document.getElementById('gridCanvas'))return;document.body.classList.add('motion-inner');if(reducedMotion||!('IntersectionObserver'in window))return;const selector=['.key-facts','.service-card','.icon-card','.scenario-card','.location-cta','.location-faq details','.faq-item','.blog-card','.blog-post-cta','.certification-card','.portfolio-card','.stripe-card',].join(', ');const fold=window.innerHeight;const items=[];document.querySelectorAll(selector).forEach((el)=>{if(el.getBoundingClientRect().top<fold)return;el.classList.add('reveal');items.push(el);});if(!items.length)return;items.forEach((el)=>{const siblings=Array.from(el.parentElement.children).filter((c)=>c.classList.contains('reveal'));const i=siblings.indexOf(el);if(i>0)el.style.transitionDelay=Math.min(i,4)*60+'ms';});const timers=new Map();const settle=(el)=>{clearTimeout(timers.get(el));timers.delete(el);el.classList.remove('reveal','is-visible');el.style.transitionDelay='';};const io=new IntersectionObserver((entries)=>{entries.forEach((entry)=>{if(!entry.isIntersecting)return;const el=entry.target;io.unobserve(el);const onEnd=(event)=>{if(event.target!==el)return;el.removeEventListener('transitionend',onEnd);settle(el);};el.addEventListener('transitionend',onEnd);timers.set(el,setTimeout(()=>{el.removeEventListener('transitionend',onEnd);settle(el);},1000));el.classList.add('is-visible');});},{rootMargin:'0px 0px -8% 0px',threshold:0.05});items.forEach((el)=>io.observe(el));});ready(function(){if(reducedMotion)return;document.querySelectorAll('.location-faq details, details.faq-item').forEach((details)=>{const summary=details.querySelector(':scope > summary');const panel=summary&&summary.nextElementSibling;if(!summary||!panel||panel.nextElementSibling||typeof panel.animate!=='function')return;let running=null;summary.addEventListener('click',(event)=>{event.preventDefault();if(running)return;const cs=getComputedStyle(panel);const open={height:panel.offsetHeight+'px',paddingTop:cs.paddingTop,paddingBottom:cs.paddingBottom,opacity:1};const shut={height:'0px',paddingTop:'0px',paddingBottom:'0px',opacity:0};panel.style.overflow='hidden';if(details.open){running=panel.animate([open,shut],{duration:200,easing:'ease'});running.onfinish=()=>{details.open=false;panel.style.overflow='';running=null;};}else{details.open=true;const grown=getComputedStyle(panel);open.height=panel.offsetHeight+'px';open.paddingTop=grown.paddingTop;open.paddingBottom=grown.paddingBottom;running=panel.animate([shut,open],{duration:240,easing:'ease'});running.onfinish=()=>{panel.style.overflow='';running=null;};}});});});ready(function(){const post=document.querySelector('main.blog-post');const navbar=document.querySelector('.navbar');if(!post||!navbar)return;const bar=document.createElement('div');bar.className='read-progress';bar.setAttribute('aria-hidden','true');navbar.appendChild(bar);let queued=false;const update=()=>{queued=false;const total=post.offsetHeight-window.innerHeight;if(total<=0){bar.style.transform='scaleX(1)';return;}
const passed=Math.min(Math.max(-post.getBoundingClientRect().top,0),total);bar.style.transform='scaleX('+(passed/total).toFixed(4)+')';};window.addEventListener('scroll',()=>{if(queued)return;queued=true;requestAnimationFrame(update);},{passive:true});window.addEventListener('resize',update);update();});ready(function(){if(reducedMotion)return;document.querySelectorAll('img[loading="lazy"]').forEach((img)=>{if(img.complete)return;img.classList.add('img-fade');const done=()=>img.classList.add('is-loaded');img.addEventListener('load',done,{once:true});img.addEventListener('error',done,{once:true});if(img.complete)done();});});})();